import {
  MeshBasicNodeMaterial,
  PlaneGeometry,
  Mesh,
  Group,
  DataTexture,
  RGBAFormat,
  ClampToEdgeWrapping,
  NearestFilter,
} from 'three/webgpu';
import {
  uv,
  mix,
  smoothstep,
  uniform,
  vec2,
  vec3,
  texture,
  fract,
  dot,
  abs,
  sub,
  mul,
  add,
  max,
  float,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    imageUrl,
    atlasRegion = { sourceRect: [0, 0, 512, 320] },
    intent = {},
  } = config;
  const colors = intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const hexToRgb = (h) => {
    const v = h.replace('#', '');
    return [parseInt(v.slice(0, 2), 16) / 255, parseInt(v.slice(2, 4), 16) / 255, parseInt(v.slice(4, 6), 16) / 255];
  };
  const ink = vec3(...hexToRgb(colors.ink));
  const surface = vec3(...hexToRgb(colors.surface));
  const accent = vec3(...hexToRgb(colors.accent));
  const paper = vec3(...hexToRgb(colors.paper));

  // ---- fallback 1x1 placeholder texture (so shader is valid synchronously) ----
  const fb = new Uint8Array([0x0b, 0x0b, 0x10, 255]);
  const placeholder = new DataTexture(fb, 1, 1, RGBAFormat);
  placeholder.needsUpdate = true;
  placeholder.magFilter = NearestFilter;
  placeholder.minFilter = NearestFilter;
  placeholder.wrapS = ClampToEdgeWrapping;
  placeholder.wrapT = ClampToEdgeWrapping;

  const texUniform = uniform(placeholder);
  const geoUniformScale = uniform(1.0);

  // ---- TSL shader: brushed-metal card w/ engineered gradient + grain ----
  const st = uv();
  const metalTex = texture(texUniform, st);

  // vertical engineered gradient: surface -> ink with a warm kiss near top
  const grad = mix(surface, ink, smoothstep(0.0, 1.0, st.y));
  const warmKiss = smoothstep(0.78, 1.0, st.y).mul(0.06);
  const gradientLayer = grad.add(warmKiss);

  // brushed metal map modulates brightness; keep it subtle so palette stays dark-first
  const metalLuma = metalTex.rgb.dot(vec3(0.299, 0.587, 0.114));
  const metalSheet = metalLuma.mul(0.55).add(0.10);

  let col = mix(gradientLayer, gradientLayer.mul(metalSheet).add(metalLuma.mul(0.12)), float(0.85));

  // machined card frame: thin chamfer darkening at edges (bevel read)
  const dx = abs(st.x.sub(0.5)).mul(2.0);
  const dy = abs(st.y.sub(0.5)).mul(2.0);
  const edge = max(dx, dy);
  const frame = smoothstep(0.93, 1.0, edge).mul(0.55);
  col = mix(col, col.mul(0.30), frame);

  // inner hairline accent stripe (<=10% of frame) — signal red engineered marker
  const stripe = smoothstep(0.90, 0.92, st.y).sub(smoothstep(0.945, 0.965, st.y));
  col = mix(col, accent.mul(0.85), stripe.mul(0.95));

  // crisp paper label tick (a single dot in upper-left as a registration mark)
  const tickUv = st.sub(vec2(0.06, 0.93));
  const tick = smoothstep(0.012, 0.0, tickUv.length());
  col = mix(col, paper, tick.mul(0.9));

  // static grain (no time — deterministic via uv hash)
  const nuv = st.mul(vec2(512.0, 320.0));
  const grain = fract(dot(nuv, vec2(12.989, 78.233))).sub(0.5).mul(0.025);
  col = col.add(grain);

  const material = new MeshBasicNodeMaterial();
  material.colorNode = col;
  material.transparent = true;
  material.opacityNode = float(1.0);

  // aspect from atlas source rect 512x320 => 1.6
  const W = 3.2;
  const H = 2.0;
  const geo = new PlaneGeometry(W, H, 1, 1);
  const mesh = new Mesh(geo, material);
  mesh.renderOrder = 2;

  const group = new Group();
  group.add(mesh);

  // subtle contact shadow behind the card (depth plane #2)
  const shadowGeo = new PlaneGeometry(W * 1.18, H * 1.18, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial();
  const shadowGrad = smoothstep(1.0, 0.0, uv().sub(0.5).length().mul(2.0));
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = shadowGrad.mul(0.45);
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.z = -0.05;
  shadow.renderOrder = 1;
  group.add(shadow);

  // ---- lift texture once available ----
  let loadedTex = null;
  if (imageUrl && ctx?.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      loadedTex = tex;
      tex.colorSpace = ctx?.THREE?.SRGBColorSpace ?? null;
      tex.wrapS = ClampToEdgeWrapping;
      tex.wrapT = ClampToEdgeWrapping;
      texUniform.value = tex;
    });
  }

  // weighted-settle entrance (no primitive requested, but motion doctrine wants weight)
  const tl = gsap.timeline();
  mesh.scale.set(0.985, 0.985, 1);
  tl.to(mesh.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 0.9, ease: 'power4.out',
  });
  tl.to(group.position, {
    z: 0.0,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  group.position.z = 0.04;

  // handlers
  group.userData.handlers = {};

  // cleanup
  group.userData.cleanup = () => {
    tl.kill();
    geo.dispose();
    shadowGeo.dispose();
    material.dispose();
    shadowMat.dispose();
    placeholder.dispose();
    if (loadedTex && loadedTex.dispose) loadedTex.dispose();
  };

  return group;
}
